# discount as a fraction of the net line amount
TIER_DISCOUNTS = {
    "silver": Decimal("0.05"),
    "platinum": Decimal("0.20"),
    "gold": Decimal("0.12"),
}

TAX_RATES = {
    "books": Decimal("0.07"),
    "food": Decimal("0.07"),
    "default": Decimal("0.19"),
}

BULK_QTY = 10
BULK_MULTIPLIER = Decimal("0.9")


def _lookup(table, key, default):
    # unhashable keys (e.g. a list as a tier) were never equal to any known value
    try:
        return table.get(key, default)
    except TypeError:
        return default


def price_line(item, customer):
    p = Decimal(str(item["price"]))
    q = item["qty"]
    if q <= 0:
        return None
    line = p * q
    if q >= BULK_QTY:
        line = line * BULK_MULTIPLIER
